style.css:
@-moz-document domain("youtube.com") {
/*==================================
      ALHAITHAM • YOUTUBE THEME
==================================*/

:root{
    --emerald:#4ee8a8;
    --emerald2:#2fc37d;
    --gold:#d5c17c;
    --glass:rgba(5,15,15,.18);
    --glass2:rgba(12,25,25,.22);
}

html,
body,
ytd-app{
    background:transparent!important;
}

/* Wallpaper */

body::before{
    content:"";
    position:fixed;
    inset:0;
    z-index:-9999;

    background:
        linear-gradient(
            rgba(0,0,0,.12),
            rgba(0,0,0,.20)
        ),
        url("https://i.postimg.cc/3wpcFHQn/alhaitham.jpg")
        center center/cover no-repeat fixed;

    filter:
        brightness(.96)
        saturate(1.25)
        contrast(1.12);
}

/* Remove TODOS os fundos */

html,
body,
#content,
#page-manager,
#columns,
#primary,
#secondary,
ytd-app,
ytd-browse,
ytd-watch-flexy,
tp-yt-app-drawer,
#background{
    background:transparent!important;
}

/* Barra superior */

ytd-masthead{
    background:rgba(8,18,18,.20)!important;
    backdrop-filter:blur(18px) saturate(180%);
    border-bottom:1px solid rgba(78,232,168,.18);
}

/* Menu */

ytd-guide-renderer,
ytd-mini-guide-renderer,
tp-yt-app-drawer{

    background:rgba(6,16,16,.18)!important;
    backdrop-filter:blur(18px);

    border-right:
        1px solid rgba(78,232,168,.12);

}

/* Pesquisa */

#search-form{
    background:rgba(8,18,18,.22)!important;

    backdrop-filter:blur(20px);

    border:1px solid rgba(78,232,168,.25);

    border-radius:50px;
}

/* Cards */

ytd-rich-item-renderer,
ytd-video-renderer,
ytd-grid-video-renderer,
ytd-compact-video-renderer{

    background:rgba(5,15,15,.16)!important;

    backdrop-filter:blur(14px);

    border-radius:18px;

    border:1px solid rgba(78,232,168,.10);

    overflow:hidden;

    transition:.30s;

}

/* Hover */

ytd-rich-item-renderer:hover,
ytd-video-renderer:hover{

    transform:
        translateY(-5px)
        scale(1.02);

    border-color:var(--emerald);

    box-shadow:

        0 0 15px rgba(78,232,168,.45),

        0 0 40px rgba(78,232,168,.18);

}

/* Miniaturas */

ytd-thumbnail img{

    border-radius:14px;

    transition:.35s;

}

ytd-thumbnail img:hover{

    transform:scale(1.04);

}

/* Texto */

*{

    color:#ffffff!important;

}

/* Links */

a:hover{

    color:var(--emerald)!important;

}

/* Botões */

button:hover,
yt-icon-button:hover{

    color:var(--emerald)!important;

    filter:drop-shadow(0 0 6px var(--emerald));

}

/* Barra vermelha -> Verde */

#progress{

    background:linear-gradient(
        90deg,
        #58ffbf,
        #18b96d
    )!important;

}

/* Scroll */

::-webkit-scrollbar{

    width:12px;

}

::-webkit-scrollbar-thumb{

    background:linear-gradient(

        var(--emerald),

        #1b8b5a

    );

    border-radius:20px;

}

/* Glow geral */

#page-manager{

    box-shadow:

    inset 0 0 250px rgba(78,232,168,.06);

}

/* Destaque do menu */

ytd-guide-entry-renderer:hover,
tp-yt-paper-item:hover{

    background:rgba(78,232,168,.10)!important;

    border-radius:14px;

}

/* Chips */

yt-chip-cloud-chip-renderer{

    background:rgba(5,15,15,.20)!important;

    border:1px solid rgba(78,232,168,.18);

    border-radius:999px;

}

yt-chip-cloud-chip-renderer:hover{

    background:rgba(78,232,168,.15)!important;

}

/* Seleção */

::selection{

    background:#39d894;

    color:#000;

}
/* ==========================
      ALHAITHAM FONT
========================== */

/* Título do vídeo */

yt-formatted-string#video-title,
#video-title,
#video-title-link,
a#video-title{

    font-family:
        Constantia,
        Cambria,
        Georgia,
        serif !important;

    font-size:21px!important;

    font-weight:700!important;

    letter-spacing:.5px!important;

    line-height:1.35!important;

    color:#F3F0E8!important;

}

/* Canal */

#channel-name,
#channel-name a{

    font-family:
        Constantia,
        Cambria,
        Georgia,
        serif!important;

    font-size:15px!important;

}

/* Visualizações */

#metadata-line,
#metadata-line span{

    font-family:
        Cambria,
        Georgia,
        serif!important;

}
}
